N["realm_4"] = function(){
  const j = JOBS[S.job];
  return {place:"境界里程碑 · 宗师",where:"修炼之地",
    text:[
      "破境后的第三日，你才敢正视自己的变化。",
      "感官像被重新打磨过：风里有三百种气味，地下有百步之外的脚步声。你握拳，掌心的力量沉稳如山，不再外溢。",
      "**宗师。**"+(j.titles&&j.titles[4]?j.titles[4]:"宗师")+"。这个名字，放在大陆任何一座城，都有人买账。",
      "你想起设定这个境界的古老规矩："+j.criterion+"。此刻再读，句句都是骨头。",
      "夜里，你盘坐时听见体内有什么东西在回响——那是业力在记账。从此往后，一举一动，都有分量。"
    ],pace:"normal",
    options:[
      {t:"回到落脚地，继续旅程",go:"arrive_generic"},
      {t:"打开地图，规划下一站",run:function(){ togglePanel("map"); }}
    ]};
};
N["realm_5"] = function(){
  const j = JOBS[S.job];
  return {place:"境界里程碑 · 大宗师",where:"修炼之地",
    text:[
      "大宗师。这个境界在大陆上，是有数的。",
      j.workDesc ? "你开始能隐约感觉到那件属于你的"+j.workDesc+"的轮廓——它还缺材料，缺火候，缺一次真正意义上的“印证”。" : "你开始能感觉到，某种“名字”在远处等你——那是一件与你性命相连的作品，还缺最后一块拼图。",
      "你翻开典籍，上面写着这个境界的锚点之法。"+j.anchor+"。你试着在心里描摹它的形状，却发现它需要你亲自去走过、经历过，才能“立”住。",
      (S.job==="thief") ? "你是盗贼。你比任何人都清楚：大宗师，已是这一行的巅峰。再往上，没有路——或者说，那条路，从来没有人走通过。" : "你隐约听说，大陆上这个境界的人，不过几十。每一个名字，都像一枚钉子，钉在大陆的记忆里。",
      "高处不胜寒。但高处，也确实看得远。"
    ],pace:"normal",
    options:[
      {t:"回到落脚地，继续旅程",go:"arrive_generic"},
      {t:"打开地图，规划下一站",run:function(){ togglePanel("map"); }}
    ]};
};
