N["world_purge"] = function(){ return {
  place:"天下大势 · 净化令",where:"圣痕司公告栏前",
  text:[
    "你进城时，正撞上圣痕司的执事们贴告示。",
    "告示上的字，墨迹还新：“净化令扩至全域。凡奥术、灵魂、归墟之学，一律查缴。窝藏者，同罪。”",
    "围观的人群鸦雀无声。一个妇人把怀里的书册往衣襟里藏了藏，指尖发白。",
    "你注意到，执事们手里多了一样东西：一枚银色的徽章，会往人脸上照。被照到的人，有的安然无恙，有的脸色骤变，被悄无声息地请走了。",
    (S.job==="灵魂法师") ? "你的心沉下去。灵魂法师，是这纸告示上点名要抓的头一等。你低头，混进人群，压了压帽檐。这座城的执事，已经比上次多了三倍。" : "你低头看了看自己的手。你身上的“气息”，经不经得起那枚银徽章一照？"
  ],pace:"normal",
  options:[
    {t:"暂避锋芒，先落脚",check:{a:"CHA",sk:"stealth",label:"避风头"},tier:{
      ok:["你压着帽檐，绕开执事的视线，从侧街溜进一家客栈。掌柜收了钱，眼皮都没抬：'住几天？'你报了个假名。","这年头，假名比真名好使。"],
      fail:["你刚要溜，一个执事的视线扫过来。你僵在原地，直到他移开视线，才慢慢挪进人群。后背已经湿了一片。"],
      crit:["你不但避开了执事，还从一个跑腿的小伙计嘴里套到话：'圣痕司的大审判长，出城去了。'他压轻声音：'去的是南方。'","南方。你想起学术城，想起那些'禁书'。"]
    },go:"world_continue"},
    {t:"凑近看看，那枚银徽章到底照什么",check:{a:"INT",sk:"detect",label:"观察"},tier:{
      ok:["你混在人群里观察：银徽章照过普通人，无波无澜；照过一两个脸色发白的人，执事们便不动声色地'请'人。你注意到，那徽章对'身上有深渊气息'的人，反应最烈。","你把这件事记在心里。"],
      fail:["你刚凑近，就被执事不耐烦地驱赶：'走开走开，别挡道！'"],
      crit:["你观察得更细：银徽章照过你时，你刻意收敛气息，它只闪了一下，执事没有深究。你顺势退开——但你也看清了：徽章背面，刻着一行小字。","'以光为界，照见归墟。'"]
    },go:"world_continue"}
  ]
  };
};
