      fail:["你笨手笨脚，打翻了一瓶溶液。老妇人痛心疾首：“我的鹿血精！”她黑着脸把你赶去洗烧杯，一下午净干杂活。"],
      critfail:["你手一抖，把一瓶红标签的试剂碰倒了。溶液渗进桌面，冒起一股黑烟。老妇人脸色铁青：“出去。今天别来了。”"]
