/* ============ 城市秘密池（与暗蚀会/深渊线衔接） ============ */
const SECRETS = [
  {cn:"夜半账房",ok:"你从后窗窥见账房里烛火通明——账本摊开，写的不是账，是一串串人名与金额。翻页的手上，戴着一枚乌黑的戒指。",fail:"账房的窗子封得死。你只听见里头打算盘的声音，噼里啪啦，一夜没停。"},
  {cn:"废弃教堂",ok:"废弃教堂的地板下压着一道暗门。你掀开一条缝——底下是一排排的铁柜，锁着。空气里飘着烛油与霉味，还有一丝若有若无的甜。",fail:"教堂的门虚掩着。你刚探头，里头传来脚步声，你只得退开。"},
  {cn:"下水道歌声",ok:"你循着夜里的低语声摸进下水道。水声里混着断断续续的念诵，像是某种祈祷，又像是某种诅咒。你记下了那段旋律。",fail:"下水道又黑又臭。你走了一段，被岔道绕晕，只得原路返回。"},
  {cn:"灰袍货商",ok:"一个灰袍货商在巷尾低价出货：铁器、药草、旧书，来路都说不清。他收钱时，袖口露出一角银月纹章——是银月商会的人，在私下销赃。",fail:"灰袍货商警觉得很，见你多看两眼，收了摊就走。你连他脸都没看清。"},
  {cn:"码头夜船",ok:"夜里的码头，一艘无灯小船靠岸。搬下来的箱子轻得出奇，却封得严实。押船的人腰上别着圣痕司的牌子，又不像公干。",fail:"码头夜巡的卫兵把你当贼，呵斥了一通。你只得悻悻离开。"},
  {cn:"药铺暗格",ok:"药铺后屋有个暗格，藏着一套缝线极细的皮甲，和一册写满符号的手抄本。你翻了两页——是某种'召唤'仪式的变体。",fail:"药铺掌柜盯着你，你只好买了包陈皮，悻悻出门。"},
  {cn:"地宫入口",ok:"城郊地宫入口的石门半掩着。门上刻着七道细纹——和你之前在商船上瞥见的乌黑牌子上的纹路，一模一样。",fail:"地宫入口的机关阵还没失效。你踩到一处，石缝里弹出锈蚀的箭矢，擦着你的耳朵钉进土里。"},
  {cn:"钟楼余烬",ok:"钟楼顶层的壁炉里，灰烬还是温的。灰烬底下压着半张烧剩的纸，上面的字迹用某种银粉写过，遇光才现——'第七夜，圣山，满月'。",fail:"钟楼里只有风声和积灰。你下楼时，总觉得背后有人目送。"}
]; window.SECRETS = SECRETS; /* /v60inj:winx2:SECRETS/ */

/* ============ 七职业专属晋升仪式（47号） ============ */
const RITUAL_TEXTS = {
  "魔法师":{title:"奥术式论证",where:"艾尔达魔法学院 · 大讲堂",text:[
    "宗师之仪，不在斗法，在立论。",
    "你被请进学院的大讲堂。台下坐着魔法协会的七位评审，个个面无表情。他们递给你一支粉笔，和一堵空白的石墙。",
    "“证明它。”首席评审说，“证明一条，从未有人证明过的法则。”",
    "你握着粉笔，在墙上画下第一条线。台下寂静。粉笔划过石面的声音，像刀锋刮过骨头。"
  ], ok:"第三十三行公式落下时，石墙上的线条自己亮了起来。评审席上，有人吸了口气一口气。", done:"从今往后，这条法则以你的名字命名。它刻在学院的白墙上，也刻在魔法的历史里。"},
  "灵魂法师":{title:"直面本心",where:"灵魂之海 · 深处",text:[
    "灵魂法师的宗师之仪，不设观众。",
    "你独自走进灵魂之海的最深处。那里没有光，没有声音，只有你自己——和你一生所有的记忆。",
    "你的另一面站在你面前。它长着你的脸，笑着：“你敢不敢，把最不敢让人知道的那件事，说出来？”",
    "这一问，问的就是你这条命，敢不敢对自己诚实。"
  ], ok:"你说出来了。那句话落地的时候，灵魂之海忽然亮了——你看见自己灵魂的全貌，包括所有丑陋的褶皱。", done:"你与自己的另一面握手言和。从这一刻起，没有人能再骗过你，包括你自己。"},
  "商人":{title:"世纪交易",where:"黄金城 · 交易所穹顶",text:[
    "商人的宗师之仪，是一场买卖。",
    "你被请上黄金城交易所的穹顶。对面坐着七个大陆最富的人，身后是无数双眼睛。",
    "他们要你完成一场“世纪交易”：用一个你无法拒绝的条件，换一个你必须放弃的东西。",
    "契约已经拟好。笔尖悬在纸上，只等你的名字。"
  ], ok:"你在契约上签下了名字。交易的内容让整个交易所倒吸一口冷气——但契约成立的那一刻，你感到'商道'在你体内真正成形。", done:"这场交易没有输家，除了那些看不透它的人。你从此懂得：真正的财富，是让别人心甘情愿地与你交易。"},
  "盗贼":{title:"众目睽睽之下消失",where:"冒险者之城 · 大宴会厅",text:[
    "盗贼的宗师之仪，是一场戏法。",
    "今晚，冒险者之城最大的宴会厅里，坐满了大陆最有头有脸的人——他们都知道，有一个“宗师”要在这里表演消失。",
    "三百双眼睛盯着你。你站在大厅中央，连空气都凝固了。",
    "你微笑。然后，你开始消失。"
  ], ok:"你没有动用一丝暗影力量——只是用光、影、视线的盲区，让三百个人同时'看不见'你。当你在他们身后重新出现时，掌声雷动。", done:"你证明了'存在即隐匿'的真意：最完美的隐匿，不是藏起来，是让所有人都以为你不在场。"},
  "战士":{title:"荣誉之战",where:"铁壁城 · 万人校场",text:[
    "战士的宗师之仪，不在纸上。",
    "铁壁城的万人校场上，战鼓擂响。你对面站着三位成名已久的战将，车轮战，一场接一场。",
    "这是荣誉之战：不许用暗器，不许用诡计，只许用刀、盾、与意志。",
    "第一声鼓响，全场寂静。你拔刀。"
  ], ok:"你连败三将，刀锋卷了三处，虎口裂开又愈合。最后一位对手收刀抱拳：'心服口服。'万人校场响起山呼。", done:"你的武名从此与铁壁城绑在一起。战场之上，敌人闻你之名，先怯三分。"},
  "牧师":{title:"圣坛立誓",where:"圣光大教堂 · 主圣坛",text:[
    "牧师的宗师之仪，是一场神迹。",
    "圣坛前，大主教将一碗圣水端到你面前：“立誓，然后，用你的信仰，救活那个孩子。”",
    "圣坛的台阶下，躺着一个气息奄奄的孩童——是圣痕司从“异端”手中救下的，也是他们审判后留下的伤者。",
    "你看着那孩子苍白的脸。神迹，从来不是恩赐，是代价。"
  ], ok:"你的手按上孩子的额头，圣水漫过指尖。孩子的呼吸平稳下来，脸色由白转红。大主教垂目，说：'主认得你的信仰。'", done:"你完成了一项真正的神迹。圣痕司从此不敢轻慢你——但他们看你的眼神，也更冷了。"},
  "术士":{title:"完美造物",where:"魔械城 · 大熔炉",text:[
    "炼金术师的宗师之仪，在火里。",
    "魔械城的大熔炉前，摆着七块凡铁。城主与发明家协会的会长，都在看着你。",
    "“把凡铁，铸成一件会自己运转的东西。”会长说，“不许用一丝魔力。”",
    "你握住锤子。炉火映在你脸上，一跳一跳的。"
  ], ok:"锤声落了三千次。那件造物在你手里完成——没有魔力，没有符文，它却自己动了起来，走了三步，才停。会长摘下帽子，向你鞠了一躬。", done:"你的造物被摆在魔械城的大厅里。它还在走着——一步，一步，提醒所有人：凡火，也能铸出奇迹。"}
};

/* ============ 七职业传奇作品（47号） ============ */
const WORK_TEXTS = {
  "魔法师":{title:"贤者之石",text:[
    "传奇境，争的是作品。",
    "你的贤者之石，在炉中炼了三年——不，是从你第一次握起法杖那天，就开始炼了。",
    "你收集的材料：元素法则的碎片、你走过的每一步、你证明过的每一条法则。",
    "最后一炉，你把自己也投了进去——不是血肉，是“知识即力量”的信念。"
  ], done:"贤者之石成。它不像石头，像一团凝固的光。握住它的人，能听见元素的声音——那是整个世界的低语。"},
  "灵魂法师":{title:"贤者之魂",text:[
    "贤者之魂，不是器物，是“另一个自己”。",
    "你把灵魂的一部分割下来，用意识法则的丝线编织，养在灵魂之海最深处。",
    "它会长大，会思考，会有自己的名字。它是你的第二颗心。",
    "完成它的那一天，你忽然明白：灵魂法师的极致，不是操控别人的灵魂，是敢于交出自己的一部分。"
  ], done:"贤者之魂睁开了眼睛。它看着你，像看着一个老朋友。从今往后，世间多了一个你，也少了一个你。"},
  "商人":{title:"贤者之金",text:[
    "贤者之金，是一枚永远增值的金币。",
    "它不值任何具体的钱——它值“等价交换”这个概念本身。",
    "你把毕生经手的每一笔交易、每一个契约、每一次“不亏本”的直觉，都熔进了这枚金币。",
    "有人出天价买它。你笑了笑，没有卖。"
  ], done:"贤者之金在掌心里发烫。你握着它，能看见这世上所有交易背后的'价'——包括那些从不明码标价的。"},
  "盗贼":{title:"贤者之影",text:[
    "贤者之影，是你的影子。",
    "普通人的影子跟着人走。你的影子，会替你先走一步。",
    "你把一生所有的隐匿、逃脱、“不存在的时刻”，都喂给了自己的影子。",
    "它渐渐有了自己的意志。它比你更懂，怎么在世间不留痕迹。"
  ], done:"贤者之影在你脚下成形。你走路时，它替你探路；你睡觉时，它替你守夜。它是你的影子，也是你的眼睛。"},
  "战士":{title:"武神之心",text:[
    "武神之心，不在胸口，在刀上。",
    "它是由你一生所有战斗“淬”出来的：败北的屈辱、胜利的狂喜、守护的执念，熔成一炉。",
    "铸刀的那天，你把刀插进校场的土里，让万人阵前的战旗影子落在刀身上。",
    "刀成之时，校场上的风，忽然停了。"
  ], done:"武神之心入鞘。你握着它，能听见万人呐喊的回声。它是刀，也是你的第二条命。"},
  "牧师":{title:"圣者之心",text:[
    "圣者之心，是一滴泪。",
    "不是你的泪——是你这一生，所有听过你祈祷的人，流下的泪。",
    "你把它们收集起来，用信仰法则的丝线串起，供奉在圣坛前。",
    "它没有光芒万丈。它只是安静地悬在那里，像一颗普通的、湿润的心。"
  ], done:"圣者之心完成了。你把它佩在胸前，它不发光，不发热，但它让所有走近你的人，都莫名地安心。"},
  "术士":{title:"贤者之石（造物）",text:[
    "炼金一脉的传奇作品，也是贤者之石。",
    "与魔法师那颗不同，你的贤者之石不凝固光——它凝固“变化”本身。",
    "你把凡铁、凡水、凡火、凡土，以及你一生对“创造”的执念，一起投入大熔炉。",
    "出炉的那一瞬，它没有固定形态。它在你掌心流动，像液态的星辰。"
  ], done:"贤者之石在你掌心定了形——不是石头，是'一切皆可转化'的真理。你握着它，就是握着万物的钥匙。"}
};

/* ============ 注册仪式/作品节点 ============ */
for(const jk in RITUAL_TEXTS){
  N["realm_ritual_"+jk] = function(){
    const R = RITUAL_TEXTS[S.job]||RITUAL_TEXTS[jk];
    return {place:"职业晋升仪式 · "+R.title, where:R.where||"仪式之地",
      text:R.text.concat([R.ok]),
      options:[
        {t:"完成仪式，立定心念",run:function(){ S.conds.rit=true; writePar(R.done,"noind"); writePar("（仪式完成。你的根基，从此有了名字。）","res"); logMsg("完成晋升仪式 · "+R.title,"l"); renderRealm(); curNode="arrive_generic"; writeNext(); }},
        {t:"打开地图，规划下一站",run:function(){ S.conds.rit=true; togglePanel("map"); }}
      ]};
  };
  N["realm_work_"+jk] = function(){
    const W = WORK_TEXTS[S.job]||WORK_TEXTS[jk];
    return {place:"传奇作品 · "+W.title, where:"铸造之地",
      text:W.text,
      options:[
        {t:"完成作品，铭刻于心",run:function(){ S.conds.work=true; S.works = S.works||{}; S.works[S.job]=W.title; writePar(W.done,"noind"); writePar("（传奇作品《"+W.title+"》已成。你的名字，从此与它绑在一起。）","res"); logMsg("铸成传奇作品 · "+W.title,"l"); renderRealm(); curNode="arrive_generic"; writeNext(); }},
        {t:"打开地图，规划下一站",run:function(){ S.conds.work=true; S.works=S.works||{}; S.works[S.job]=W.title; togglePanel("map"); }}
      ]};
  };
}

/* ============ 神恩 · 第二职业选择节点（46号：神明准则/神位） ============ */
N["realm_godfavor"] = function(){
  const opts = [];
  for(const jk in JOBS){
    if(jk===S.job) continue;
    const j=JOBS[jk];
    opts.push({t:"【"+j.cn+"】"+j.deity.split("（")[0]+" · "+j.criterion,run:function(){ godFavorChoose(jk); }});
  }
  opts.push({t:"神恩太重，我受不起（放弃）",run:function(){ S.flags.god_favor=false; writePar("你掐灭了香。神明没有挽留。这条路，本就不该强求。","noind"); curNode="arrive_generic"; writeNext(); }});
  return {place:"神恩 · 择路", where:"修炼之地 · 香案前",
    text:["光柱悬在你头顶，像一只垂落的眼睛。","它没有说话，但你知道它在等：等你选一条路。","七条路在你眼前展开。你只能选一条——作为你“第二根基”的路。","记住：神恩只此一次。选定了，就是一生。"],pace:"light",
    options:opts};
};


