N["world_silverroad_arm_recruit"]={
  place:"自由城邦 · 酒馆", where:"",
  text:[
    "他愣住了。",
    "“我？”他指了指自己的断臂，“我一个废人，能做什么？”",
    "“你熟悉情况。”你说，“而且你想报仇，对吧？”",
    "他沉默了很久。然后他站起来，把酒杯里剩下的酒一口喝干。",
    "“好。”他说，“我跟你去。但有个条件——如果我变成了他们那样，你杀了我。”",
    "他伸出右手。你握了握。手很粗糙，但很有力。",
    "“我叫汉斯。”他说，“前银月家族商队护卫。”"
  ],pace:"normal",
  options:[{t:"带上汉斯，出发", effect:{flag:"hans_ally",item:"汉斯加入"}, go:"arrive_generic"}]
};

N["world_silverroad_silvermoon"]={
  place:"自由城邦 · 银月家族据点", where:"",
  text:[
    "银月家族在自由城邦的据点，是一座不大的仓库。门口挂着银色的月亮纹章。",
    "你走进去，一个管事模样的人迎上来。“有什么事？”",
    "“我在查银穗商路的事。你们最近一支商队失踪了，领队叫卡尔。”",
    "管事的脸色变了。“你是城主府派来的？”",
    "“算是吧。”你拿出城主令牌。",
    "他看了令牌，态度软了下来。“卡尔的商队，三天前出发的。带了二十车货，十二个护卫。按脚程，现在应该到中途的乌鸦驿了。”",
    "“但我们联系不上他。商队之间有约定——每天晚上在驿站点火传信。乌鸦驿的火，三天没点了。”"
  ],pace:"normal",
  options:[
    {t:"“乌鸦驿在哪里？”", go:"world_silverroad_crowloc"},
    {t:"“卡尔是什么样的人？”", go:"world_silverroad_carl"}
  ]
};

N["world_silverroad_crowloc"]={
  place:"自由城邦 · 银月家族据点", where:"",
  text:[
    "管事拿出一张地图，铺在桌上。",
    "“乌鸦驿在这里。”他指了指地图上的一个点，“商路中段，离自由城邦五天路程。十年前因为闹鬼废弃了——当然，那是官方说法。”",
    "“实际原因是——那个驿站的人，一夜之间全死了。死状很惨，官方说是瘟疫，但我们做买卖的人都知道，不是瘟疫。”",
    "“是什么？”",
    "管事压轻声音。“是暗蚀会。那个驿站，曾经是暗蚀会的一个据点。被教会清洗过，但没洗干净。”",
    "“所以你看——”他指了指地图，“商队在乌鸦驿失踪，不是巧合。”"
  ],pace:"normal",
  options:[{t:"记下位置，离开", effect:{flag:"crow_station_known",flag:"crow_station_darkcult"}, go:"arrive_generic"}]
};

N["world_silverroad_carl"]={
  place:"自由城邦 · 银月家族据点", where:"",
  text:[
    "“卡尔？”管事想了想，“老资格的领队了。走了二十年商路，从没出过事。”",
    "“他这个人，谨慎得很。每次出发前，都要把路线、天气、护卫配置反复检查三遍。”",
    "“所以他的商队失踪，我们都觉得——不正常。以卡尔的谨慎，就算遇到强盗，也不至于全军覆没。”",
    "“除非——”管事的脸色沉了下来，“遇到的不是普通的强盗。”"
  ],pace:"light",
  options:[{t:"谢过管事，出发调查", effect:{flag:"carl_profile"}, go:"arrive_generic"}]
};

