N["aurelian_substitute"]={
  place:"地下图书馆最深层 · 封印台", where:"",
  text:[
    "你说出那两个字的时候，奥雷利安的手顿了一下。",
    "“你确定？”他问，“你甚至不认识她。”",
    "“我确定。”",
    "奥雷利安看了你很久。然后，他笑了。是那种很淡的、带着一丝欣慰的笑。",
    "“黄林晶当年也说过同样的话。”他说，“但他最后退缩了。不是因为他自私，是因为他还有未完成的事。”",
    "“你呢？你有未完成的事吗？”",
    "你想了想。",
    "“有。”你说，“但这件事，更重要。”",
    "奥雷利安点了点头。",
    "“好吧。”他说，“但现在还不行。你的灵魂还不够强。分出三成，你会崩溃。你需要至少达到大宗师境，灵魂才足够稳固。”",
    "“到那时候，如果你还愿意，”他说，“我会帮你。”",
    "他从长袍里掏出一个吊坠，递给你。吊坠是银色的，里面有一滴液体，在发光。",
    "“这是塞拉芬的一滴眼泪。”他说，“她被封印前流的最后一滴眼泪。带着它，你能感觉到她的存在。也能——在关键时刻，召唤她的力量一次。”",
    "“但只能用一次。用了，这滴眼泪就会消失。”"
  ],pace:"normal",
  options:[{t:"收下吊坠，告辞", effect:{item:"塞拉芬的眼泪",flag:"seraphine_substitute_promise",karma:3}, go:"arrive_generic"}]
};
N["aurelian_promise"]={
  place:"地下图书馆最深层 · 封印台", where:"",
  text:[
    "塞拉芬看着你，看了很久。",
    "然后，她的笑容变了。变得更温柔了，也更悲伤了。",
    "“你和他一样。”她说，“都喜欢说这种不负责任的话。”",
    "“墨丘利也这么说。他每天都来，每天都说“一定会有办法的”。说了三十年。”",
    "“但我知道，没有办法。”她说，“我自己的灵魂，我最清楚。那部分黑色，已经长在我身上了。剜掉，我就死了。不剜，我就会变成怪物。”",
    "“但谢谢你。”她说，“谢谢你愿意骗我。”",
    "她闭上眼睛。光罩上的黑色纹路，停止了蔓延。",
    "奥雷利安走到你身边，轻声说：",
    "“她很久没说这么多话了。”他说，“你对她有影响。也许，你说的办法，真的存在。”",
    "“去找核心铸印吧。”他说，“如果这个世界上有什么能救她，那一定是核心铸印。”"
  ],pace:"normal",
  options:[{t:"告别塞拉芬和奥雷利安", effect:{flag:"seraphine_promise",flag:"core_seal_quest",karma:2}, go:"arrive_generic"}]
};
N["aurelian_advice"]={
  place:"地下图书馆最深层", where:"",
  text:[
    "奥雷利安坐回地上，端起茶杯。茶已经凉了，但他还是喝了一口。",
    "“三个建议。”他说，“第一，不要抗拒那根线。抗拒会让它变粗。接受它，控制它，让它成为你的一部分。就像一条河，你不能堵住它，你只能引导它。”",
    "“第二，不要过度使用灵魂魔法。每次使用，线都会变粗一点。给自己设一个限度，超过了，就停下来。”",
    "“第三——”他看着你，眼神很认真，“找一个锚点。一个能让你在深渊的诱惑面前，保持自我的东西。可以是一个人，可以是一件事，可以是一个信念。”",
    "“黄林晶的锚点，是他想保护这个世界。墨丘利的锚点，是塞拉芬。我的锚点——”他指了指光门，“是这扇门后面的东西。”",
    "“你的锚点是什么？”",
    "你想了想。",
    "你还不知道。",
    "“不知道也没关系。”奥雷利安说，“你会找到的。在你最危险的时候，锚点会自己出现。”",
    "他站起身，走到光门前。",
    "“好了，”他说，“茶凉了，话也说完了。你该走了。”",
    "“但记住——”他回头看了你一眼，“不要一个人扛所有的事。黄林晶就是因为什么都自己扛，最后才差点变成了他最不想变成的那种人。”"
  ],pace:"normal",
  options:[{t:"谢过奥雷利安，离开", effect:{flag:"aurelian_advice",karma:1}, go:"arrive_generic"}]
};
N["aurelian_brave"]={
  place:"地下图书馆最深层", where:"",
  text:[
    "奥雷利安看着你，嘴角扬了扬。",
    "“不怕？”他说，“黄林晶也说过这句话。然后，他在深渊面前，腿软了。”",
    "“不是因为他胆小。是因为深渊的存在，本身就会让任何生物感到恐惧。那是刻在灵魂里的本能。就像人怕火，怕高，怕死一样。”",
    "“你说不怕，要么是你还没真正接触过深渊，要么——你的灵魂比你以为的更强大。”",
    "他走到你面前，盯着你的眼睛。",
    "你感觉到了一股力量，从他的眼睛里涌出来，直接撞进你的灵魂。那股力量很强大，像一座山压下来。",
    "你咬紧牙关，没有后退。",
    "三秒后，奥雷利安收回了视线。",
    "“有意思。”他说，“你的灵魂，比我想象的稳。大多数人在我的视线下，三秒就会跪下。”",
    "“你站了五秒。”",
    "他从长袍里掏出一本书，递给你。",
    "“《灵魂屏障入门》。”他说，“我写的。教你怎么在灵魂和深渊之间，建一道屏障。虽然不能完全隔绝，但能减缓侵蚀的速度。”",
    "“别告诉墨丘利我给你的。”他说，“那个老家伙说我的书写得太晦涩，不适合初学者。但我觉得，你能看懂。”"
  ],pace:"normal",
  options:[{t:"收下书，谢过奥雷利安", effect:{item:"灵魂屏障入门",skillUp:"arcana",flag:"aurelian_respect"}, go:"arrive_generic"}]
};
N["aurelian_where"]={
  place:"地下图书馆最深层", where:"",
  text:[
    "“这里？”奥雷利安环顾了一下四周，“地下图书馆第四层，最深层。也是整个大陆，离深渊最近的地方。”",
    "“不是物理上的近。是灵魂上的近。古代艾尔达文明把这里建在一条灵魂能量的脉络上，这条脉络，直通深渊。”",
    "“黄林晶当年发现了这个地方，把它改造成了封印点。这扇光门后面，是第七印的锚点。”",
    "“我在这里守了三十年。”他说，“不是因为我喜欢这里。是因为如果我走了，封印就会松动。”",
    "“你知道三十年是什么概念吗？”他问，“对半神来说，三十年不算长。但对一个“人”来说，三十年，足够让一个婴儿变成中年人，足够让一段感情从热烈变成平淡，足够让一个王朝从兴盛走向衰落。”",
    "“我在这里，看着上面的世界变了三十年。而我，连一杯热茶都喝不上。”",
    "他举起茶杯，示意了一下。",
    "“所以，”他说，“有话快说。我这杯茶，已经凉了三次了。”"
  ],pace:"normal",
  options:[
    {t:"“七印的事。”", go:"aurelian_seals"},
    {t:"“你不觉得孤独吗？”", go:"aurelian_lonely"}
  ]
};
N["aurelian_lonely"]={
  place:"地下图书馆最深层", where:"",
  text:[
    "奥雷利安愣了一下。",
    "然后，他笑了。这次是真的笑，不是那种敷衍的、客气的笑，是一种很真实的、带着一点苦涩的笑。",
    "“孤独？”他重复了一遍，“三十年了，你是第一个问我这个问题的人。”",
    "“墨丘利每天来，但他只关心塞拉芬。学院的人偶尔来，但他们只关心封印稳不稳。暗蚀会的人来过几次，但他们只关心怎么破坏封印。”",
    "“没有人问我，孤不孤独。”",
    "他喝了一口凉茶。",
    "“孤独啊。”他说，“当然孤独。但孤独久了，就习惯了。习惯了，就不觉得孤独了。”",
    "“就像这杯茶。刚凉的时候，觉得难喝。喝了三十年，就觉得，凉茶也有凉茶的味道。”",
    "他看着你，眼神很柔和。",
    "“谢谢你问。”他说，“虽然这是一个没有意义的问题，但我很高兴有人问。”",
    "大厅里安静了一会儿。",
    "“好了。”他站起身，“感伤够了。说正事吧。你来找我，不会只是为了问我孤不孤独吧？”"
  ],pace:"normal",
  options:[
    {t:"“七印的事。”", go:"aurelian_seals"},
    {t:"“塞拉芬的事。”", go:"aurelian_seraphine"}
  ]
};
N["aurelian_observe"]={
  place:"地下图书馆最深层", where:"",
  text:[
    "你没有说话，而是仔细观察周围。",
    "通道的墙壁上，那些古代艾尔达文字，你不认识。但你能感觉到，它们在发光。不是物理上的光，是灵魂上的光。每一个字，都像一个小小的灵魂，在墙壁里沉睡。",
    "你看向光门。光门后面，有一股力量在涌动。不是邪恶的力量，是一种……古老的力量。像大海，像星空，像时间本身。",
    "你看向奥雷利安。他站在那里，端着茶杯，看起来很普通。但你能感觉到，他的灵魂像一座山。不，比山更大。像一片大陆。他的灵魂已经和这扇光门、和这个地下空间、甚至和第七印的锚点，融合在了一起。",
    "他不是在守护封印。他已经变成了封印的一部分。",
    "你突然明白了。他说他三十年没出过这扇门，不是因为他不能出去，是因为他出去了，封印就会弱一分。他把自己，活成了一道封印。",
    "“看够了？”奥雷利安说，“你比我想象的敏锐。大多数人，只能看到我端着茶杯。你看到了更多。”"
  ],pace:"normal",
  options:[
    {t:"“你把自己变成了封印。”", go:"aurelian_seal_himself"},
    {t:"“七印的事。”", go:"aurelian_seals"}
  ]
};
N["aurelian_seal_himself"]={
  place:"地下图书馆最深层", where:"",
  text:[
    "奥雷利安的手顿了一下。茶杯里的水，晃了晃。",
    "“你看出来了。”他说，语气很平静，“对。我把自己的灵魂，和封印融合了。这样，封印就多了一层保障。”",
    "“代价是，我不能离开这里。离开超过一天，我的灵魂就会开始消散。”",
    "“值得吗？”你问。",
    "奥雷利安沉默了很久。",
    "“三十年前，塞拉芬被侵蚀的时候，我问过自己同样的问题。”他说，“值得吗？为了一个被深渊侵蚀的人，把自己困在这里一辈子。”",
    "“那时候，墨丘利跪在我面前，求我救她。他是大陆最骄傲的魔法师，从来没求过人。但那天，他跪在我面前，头都磕破了。”",
    "“我说，救她可以，但需要一个锚点。一个愿意把灵魂和封印融合的人。”",
    "“墨丘利说他来。但我说不行。他的灵魂太骄傲了，和封印融合，会冲突。只有我的灵魂，足够平和，足够稳定。”",
    "“所以我来了。”他说，“一待，就是三十年。”",
    "“值得吗？”他重复了一遍你的问题，笑了，“我不知道。但如果重来一次，我还是会这么选。”",
    "“因为墨丘利是我朋友。而朋友的请求，不能拒绝。”"
  ],pace:"normal",
  options:[{t:"沉默，向奥雷利安鞠了一躬", effect:{flag:"aurelian_respect_deep",karma:2}, go:"aurelian_seals"}]
};
N["aurelian_silence"]={
  place:"地下图书馆最深层", where:"",
  text:[
    "你没有说话。",
    "奥雷利安也没有说话。",
    "两个人就那样坐着，听着地下图书馆里的寂静。",
    "过了很久，奥雷利安开口了。",
    "“你是个好人。”他说，“不是那种烂好人。是那种，在该沉默的时候沉默，在该说话的时候说话的人。”",
    "“这个世界上，聪明人太多，好人太少。而能把聪明和善良结合在一起的人，更少。”",
    "“黄林晶是一个。墨丘利算半个。你——”他看着你，“可能是第三个。”",
    "他站起身，走到光门前，手一挥，光门开了一条缝。",
    "从缝里，你看到了。一个白色的身影，悬浮在封印台上。她的长发在无风的空间里飘动，像黑色的水。",
    "“她听到了我们的对话。”奥雷利安说，“她在哭。”",
    "你仔细看。果然，塞拉芬的眼角，有一滴泪。那滴泪没有落下来，而是悬浮在她的脸颊旁边，像一颗珍珠。",
    "“三十年了，”奥雷利安说，“她第一次哭。”",
    "光门合上了。",
    "“好了。”奥雷利安转过身，“你该走了。这里的空气，对你的灵魂不好。待久了，那根线会变粗。”"
  ],pace:"normal",
  options:[{t:"告辞，离开地下图书馆", effect:{flag:"aurelian_silence_moved",karma:1}, go:"arrive_generic"}]
};




